import{_ as e,o as a,c as t,a9 as n}from"./chunks/framework.asyjyako.js";const u=JSON.parse('{"title":"Julia and native profiling","description":"","frontmatter":{},"headers":[],"relativePath":"native-profiling.md","filePath":"native-profiling.md","lastUpdated":null}'),s={name:"native-profiling.md"};function r(o,i,l,p,d,c){return a(),t("div",null,[...i[0]||(i[0]=[n(`<h1 id="Julia-and-native-profiling" tabindex="-1">Julia and native profiling <a class="header-anchor" href="#Julia-and-native-profiling" aria-label="Permalink to &quot;Julia and native profiling {#Julia-and-native-profiling}&quot;">​</a></h1><p>Locate where an operation spends time.</p><p>Use Julia&#39;s tools first. Use a native profiler to inspect a C/C++/Fortran dependency or activity outside Julia.</p><h2 id="Pick-an-instrument-from-the-question" tabindex="-1">Pick an instrument from the question <a class="header-anchor" href="#Pick-an-instrument-from-the-question" aria-label="Permalink to &quot;Pick an instrument from the question {#Pick-an-instrument-from-the-question}&quot;">​</a></h2><ul><li><p>Slower than before? BenchmarkTools or Chairmarks, before and after.</p></li><li><p>Which calls take the time? Julia CPU profiler, then perf or VTune for native frames.</p></li><li><p>Waiting rather than computing? Wall-time profile; WPR/WPA or perf/bpftrace for system traces.</p></li><li><p>Which Julia code allocates? <code>Profile.Allocs</code>; a heap snapshot for retained objects.</p></li><li><p>Process memory growing? <a href="./process-memory">Process-memory counters</a>; Massif or heaptrack for native heap.</p></li><li><p>Slow first call? Measure startup and first call separately; SnoopCompile for compilation.</p></li><li><p>More threads not helping? Repeat at several thread counts; inspect scheduling and locks.</p></li><li><p>GPU work? A device profiler such as Nsight; synchronize before timing.</p></li><li><p>Native dependency misusing memory? Memcheck or a sanitizer build.</p></li></ul><p>Native tools require separate installation. PerfChecker can <strong>prepare commands</strong> for some of them; listing a tool does not mean it can run it or import its output.</p><h2 id="Static-analysis-and-compilation" tabindex="-1">Static analysis and compilation <a class="header-anchor" href="#Static-analysis-and-compilation" aria-label="Permalink to &quot;Static analysis and compilation {#Static-analysis-and-compilation}&quot;">​</a></h2><p>These inspect code, not measured cost. Treat a diagnostic as a hypothesis and confirm practical cost with a benchmark.</p><ul><li><p><strong>JET</strong> — follows the inferred call graph; reports possible runtime dispatch and inference pitfalls.</p></li><li><p><strong>Cthulhu</strong> — descend through inferred code to see where type information becomes imprecise.</p></li><li><p><strong>SnoopCompile</strong> — examine inference work that contributes to compilation.</p></li><li><p><strong>AllocCheck</strong> — statically visible allocation and dispatch paths in generated LLVM.</p></li><li><p><strong>PrecompileTools / PackageCompiler</strong> — change the startup/artifact tradeoff; compare cold import, first call, steady state, build cost and artifact size separately.</p></li><li><p><strong>Aqua</strong> — package quality (ambiguities, unused type parameters). A pass is not a latency or memory budget.</p></li></ul><h2 id="Linux-native-tools" tabindex="-1">Linux native tools <a class="header-anchor" href="#Linux-native-tools" aria-label="Permalink to &quot;Linux native tools {#Linux-native-tools}&quot;">​</a></h2><p><code>native_tool_plan</code> prepares argument vectors for Memcheck, Callgrind, Cachegrind, Massif, heaptrack, perf and VTune. It checks local executable presence without starting a process.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PerfChecker</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">plan </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> native_tool_plan</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:memcheck</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;native_case.jl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    project </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;perf&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, output </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;results/memcheck&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    suppressions </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;contrib/valgrind-julia.supp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Valgrind needs <code>--smc-check=all-non-file</code> for Julia&#39;s JIT. Some investigations need Julia built with memory pools disabled. A zero exit is not enough without the workload oracle and reviewed diagnostics.</p><ul><li><p><strong>Memcheck</strong> — invalid reads/writes, uninitialized values, leaks. Correctness diagnostics, not speed.</p></li><li><p><strong>Callgrind</strong> — instruction execution and call relationships. Read self vs inclusive cost; not elapsed time.</p></li><li><p><strong>Cachegrind</strong> — instructions plus simulated caches/branches. Simulation, disabled by default, not modern CPUs.</p></li><li><p><strong>Massif</strong> — sampled native heap usage. Peak vs endpoint; the time axis may be instructions.</p></li><li><p><strong>heaptrack</strong> — native allocation stacks. Temporary activity vs retained memory.</p></li><li><p><strong>perf / LIKWID / PAPI</strong> — hardware counters. Record multiplexing and affinity; a missing counter is not zero.</p></li></ul><p>Units matter: instruction counts, cache misses and heap sizes are not elapsed seconds. Use an ordinary benchmark for the final comparison.</p><h2 id="Windows,-traces-and-instrumented-builds" tabindex="-1">Windows, traces and instrumented builds <a class="header-anchor" href="#Windows,-traces-and-instrumented-builds" aria-label="Permalink to &quot;Windows, traces and instrumented builds {#Windows,-traces-and-instrumented-builds}&quot;">​</a></h2><ul><li><p><strong>WPR/WPA</strong> record and analyze ETW traces for scheduling, I/O and system activity.</p></li><li><p><strong>VTune</strong> is another CPU analysis route.</p></li><li><p>Julia exposes Tracy/VTune timing zones and DTrace/bpftrace probes; coverage depends on the build.</p></li><li><p><strong>Sanitizers</strong> diagnose memory errors or races; their overhead cannot be treated as production performance.</p></li></ul><h2 id="GPU,-distributed,-foreign-runtimes" tabindex="-1">GPU, distributed, foreign runtimes <a class="header-anchor" href="#GPU,-distributed,-foreign-runtimes" aria-label="Permalink to &quot;GPU, distributed, foreign runtimes {#GPU,-distributed,-foreign-runtimes}&quot;">​</a></h2><ul><li><p>CUDA: synchronize before comparing completed costs; separate host/device transfer from kernels.</p></li><li><p>AMDGPU/rocprof, oneAPI, MPI/Dagger traces and NPU providers remain environment-specific candidates.</p></li><li><p>Native dependency fingerprints, actual devices, transfer boundaries, rank identities and fallback detection are required before interpreting these measurements.</p></li><li><p>macOS tooling stays inventoried; no Mac validation is claimed.</p></li></ul><h2 id="Before-calling-an-adapter-supported" tabindex="-1">Before calling an adapter supported <a class="header-anchor" href="#Before-calling-an-adapter-supported" aria-label="Permalink to &quot;Before calling an adapter supported {#Before-calling-an-adapter-supported}&quot;">​</a></h2><p>Run four controls: a healthy workload, a known native leak, a known CPU hotspot and a child-process workload. Check symbol/source attribution, nonzero diagnostics for injected defects, bounded cancellation, artifact completeness and matching dependency identities. Then rerun unchanged controls without the profiler to measure its perturbation. Windows and Linux need their own evidence. <a id="Julia-and-native-performance-tools"></a><a id="Choose-an-instrument-from-the-question"></a><a id="JET:-possible-inference-and-dispatch-problems"></a><a id="Cthulhu:-inspect-the-compiler&#39;s-view-interactively"></a><a id="SnoopCompile:-investigate-compilation-work"></a><a id="AllocCheck:-inspect-possible-allocation-paths"></a><a id="Precompilation-tools-and-package-quality"></a><a id="Memcheck:-invalid-memory-operations-and-leaks"></a><a id="Callgrind:-instruction-cost-along-a-call-graph"></a><a id="Cachegrind:-instructions-and-optional-simulated-caches"></a><a id="Massif-and-heaptrack:-native-heap-growth"></a><a id="Hardware-counters:-events-on-the-actual-processor"></a><a id="GPU,-distributed-and-foreign-runtimes"></a><a id="Qualification-experiment"></a></p>`,21)])])}const m=e(s,[["render",r]]);export{u as __pageData,m as default};
